-- Datelog: The Crowd — richer, non-identifying detail on BOTH people + date context.
-- Apply AFTER community.sql and examples.sql, in the Supabase SQL editor. Idempotent.
-- Stored in one jsonb column "details", validated server-side against fixed choice lists:
--   you/them: age, height, work, education, looking for, wants kids, drinks, smokes, religion & politics importance,
--             history (married/divorced/kids), up to 3 vibe tags
--   ctx: how long talking, messaging, chemistry so far, who asked, activity, time of day, which date
--   like / flag: one line each, max 80 chars, no @, links or 3+ digit numbers
-- Generated by tools/gen_details_sql.py (choice lists shared with index.html).

alter table public.community_posts add column if not exists age_band   text;
alter table public.community_posts add column if not exists gender     text;
alter table public.community_posts add column if not exists seeking    text;
alter table public.community_posts add column if not exists is_example boolean not null default false;
alter table public.community_posts add column if not exists ex_weekday smallint;
alter table public.community_posts add column if not exists details    jsonb;

create or replace function public.crowd_details_ok(j jsonb) returns boolean language plpgsql immutable set search_path = public as $$
declare A jsonb := '{"person": {"age": ["20–24", "25–29", "30–34", "35–39", "40–49", "50+"], "height": ["Under 5′4″", "5′4″–5′7″", "5′8″–5′11″", "6′0″–6′2″", "6′3″+"], "job": ["Tech", "Creative/arts", "Healthcare", "Finance/business", "Law", "Education", "Trades", "Hospitality", "Student", "Founder", "Other"], "edu": ["High school", "Some college", "Bachelor’s", "Master’s", "Doctorate/MD/JD"], "want": ["Casual", "Dating", "Relationship", "Marriage", "Not sure"], "kids": ["Wants kids", "Open to it", "Doesn’t want", "Not sure"], "drinks": ["Never", "Socially", "Often"], "smokes": ["No", "Sometimes", "Yes"], "religion": ["Not really", "Somewhat", "A lot"], "politics": ["Not really", "Somewhat", "A lot"], "past": ["Never married", "Divorced", "Has kids", "Divorced + kids"], "vibe": ["Funny", "Adventurous", "Ambitious", "Chill", "Nerdy", "Artsy", "Outdoorsy", "Homebody", "Social", "Romantic", "Sarcastic", "Sporty"]}, "ctx": {"talking": ["Just matched", "Under a week", "1–4 weeks", "1+ month"], "msgs": ["Barely", "A few a day", "All day"], "chem": ["Low", "Medium", "High", "Off the charts"], "asked": ["I asked", "They asked", "Mutual"], "act": ["Coffee shop", "Bar", "Restaurant", "Hike", "Museum/gallery", "Show/concert", "Sports/game", "Cooking", "Beach", "Other"], "tod": ["Morning", "Afternoon", "Evening", "Late night"], "num": ["1st", "2nd", "3rd+"]}, "multi": {"vibe": 3}, "text": {"like": 80, "flag": 80}}'::jsonb; k text; r record; e jsonb; sec text;
begin
  if j is null then return true; end if;
  if jsonb_typeof(j) <> 'object' or pg_column_size(j) > 4000 then return false; end if;
  for k in select jsonb_object_keys(j) loop
    if k in ('you','them','ctx') then
      sec := case when k = 'ctx' then 'ctx' else 'person' end;
      if jsonb_typeof(j->k) <> 'object' then return false; end if;
      for r in select key, value from jsonb_each(j->k) loop
        if not (A->sec) ? r.key then return false; end if;
        if sec = 'person' and (A->'multi') ? r.key then
          if jsonb_typeof(r.value) <> 'array' or jsonb_array_length(r.value) > (A->'multi'->>r.key)::int then return false; end if;
          for e in select value from jsonb_array_elements(r.value) loop
            if jsonb_typeof(e) <> 'string' or not (A->sec->r.key) @> jsonb_build_array(e) then return false; end if;
          end loop;
        elsif jsonb_typeof(r.value) <> 'string' or not (A->sec->r.key) @> jsonb_build_array(r.value) then return false;
        end if;
      end loop;
    elsif (A->'text') ? k then
      if jsonb_typeof(j->k) <> 'string' or char_length(j->>k) > (A->'text'->>k)::int or (j->>k) ~* '(@|https?:|www\.|[0-9]{3})' then return false; end if;
    else return false;
    end if;
  end loop;
  return true;
end $$;
alter table public.community_posts drop constraint if exists cp_details_chk;
alter table public.community_posts add  constraint cp_details_chk check (public.crowd_details_ok(details));

drop function if exists public.list_community(text);
create function public.list_community(p_voter text default null)
returns table (id uuid, nick text, date_type text, area text, day_label text, met text, excite smallint, outcome text,
               yes_votes int, no_votes int, my_pick text, created_at timestamptz,
               age_band text, gender text, seeking text, is_example boolean, details jsonb)
language sql security definer set search_path = public stable as $$
  with t as (select (now() at time zone 'America/Los_Angeles')::date as d)
  select p.id, p.nick, p.date_type, p.area,
         case when p.is_example and p.ex_weekday is not null then
           (select case ((p.ex_weekday - extract(dow from t.d)::int + 7) % 7)
                     when 0 then 'today' when 1 then 'tomorrow'
                     else trim(to_char(t.d + ((p.ex_weekday - extract(dow from t.d)::int + 7) % 7), 'Day')) end from t)
         else p.day_label end,
         p.met, p.excite, p.outcome,
         (select count(*)::int from community_votes v where v.post_id = p.id and v.pick = 'yes'),
         (select count(*)::int from community_votes v where v.post_id = p.id and v.pick = 'no'),
         (select v.pick from community_votes v where v.post_id = p.id and v.voter_id = p_voter),
         p.created_at, p.age_band, p.gender, p.seeking, p.is_example, p.details
  from community_posts p
  where p.is_example or p.expires_at > now()
  order by p.is_example, (p.outcome is not null), p.created_at desc
  limit 100;
$$;
revoke all on function public.list_community(text) from public;
grant execute on function public.list_community(text) to anon, authenticated;

drop function if exists public.post_community(text,text,text,text,text,int,int,text);
drop function if exists public.post_community(text,text,text,text,text,int,int,text,text,text,text);
drop function if exists public.post_community(text,text,text,text,text,int,int,text,text,text,text,jsonb);
create function public.post_community(p_nick text, p_type text, p_area text, p_day text, p_met text, p_excite int, p_days_until int, p_poster text,
                                      p_age text default null, p_gender text default null, p_seeking text default null, p_details jsonb default null)
returns json language plpgsql security definer set search_path = public as $$
declare v_id uuid; v_tok text;
begin
  p_nick := btrim(coalesce(p_nick,''));
  if char_length(p_nick) < 1 or char_length(p_nick) > 16 or p_nick ~ '[@/:<>]' or p_nick ~ '\d{3}' or p_nick ~* '(https?|www\.)' then raise exception 'bad nick' using errcode='22023'; end if;
  if p_days_until is null or p_days_until < 0 or p_days_until > 21 then raise exception 'bad day' using errcode='22023'; end if;
  if p_poster is null or p_poster !~ '^[0-9a-f]{16,64}$' or p_poster = repeat('0',32) then raise exception 'bad poster' using errcode='22023'; end if;
  if not public.crowd_details_ok(p_details) then raise exception 'bad details' using errcode='22023'; end if;
  if (select count(*) from community_posts where poster_id = p_poster and created_at > now() - interval '1 day') >= 5 then raise exception 'rate limit' using errcode='P0001'; end if;
  if (select count(*) from community_posts where created_at > now() - interval '1 day' and not is_example) >= 1000 then raise exception 'busy' using errcode='P0001'; end if;
  v_tok := replace(gen_random_uuid()::text,'-','') || replace(gen_random_uuid()::text,'-','');
  insert into community_posts (token_hash, poster_id, nick, date_type, area, day_label, met, excite, expires_at, age_band, gender, seeking, is_example, details)
  values (encode(sha256(convert_to(v_tok,'UTF8')),'hex'), p_poster, p_nick, p_type, p_area, p_day, p_met, p_excite,
          date_trunc('day', now()) + make_interval(days => p_days_until + 4), nullif(p_age,''), nullif(p_gender,''), nullif(p_seeking,''), false,
          nullif(p_details, '{}'::jsonb))
  returning id into v_id;
  return json_build_object('id', v_id, 'token', v_tok);
end $$;
revoke all on function public.post_community(text,text,text,text,text,int,int,text,text,text,text,jsonb) from public;
grant execute on function public.post_community(text,text,text,text,text,int,int,text,text,text,text,jsonb) to anon, authenticated;

